entries[394801] = { ["name"] = "Ruhlose Bande", ["text"] = "100 Meter Reichweite\nSofort\n'Ruhlose Klingen' wirkt sich zusätzlich auf Gruppenmitglieder innerhalb von 40 Metern aus und verringert die verbleibende Abklingzeit einer wichtigen Offensivfähigkeit um 0.2 Sek. pro verbrauchtem Combopunkt.\n\nJedes Gruppenmitglied kann nur einmal alle 2.0 Sek. von diesem Effekt profitieren." }
