entries[395152] = { ["name"] = "Schwarzmacht", ["text"] = "1% von Grundmana\nWirken in 1.5 sek. 30 sek. Abklingzeit\nErhöht den Primärwert Eurer 4 nächsten Verbündeten um (5 + 0 )% Eures eigenen Primärwerts und Ihr verursacht 20% mehr Schaden. Hält 10 Sek. lang an.\n\nKann nur jeweils 4 Verbündete gleichzeitig betreffen und wirkt sich nicht auf Tanks und Heiler aus.\n\n'Eruption', [ Atem der Äonen : 'Atem der Äonen' / 'Tiefer Atem'] und Eure ermächtigten Zauber verlängern die Dauer dieser Effekte." }
entries[395153] = { ["name"] = "Sande der Zeit", ["text"] = "' Eruption ' [ Frühlingstraum : oder ' Smaragdblüte ' ] erhöht die Dauer Eurer aktiven Effekte von 'Schwarzmacht' um 1 Sek.\n\nEure ermächtigten Zauber erhöhen die Dauer Eurer aktiven Effekte von 'Schwarzmacht' um 2 Sek.\n\n[ Atem der Äonen : ' Atem der Äonen ' / ' Tiefer Atem '] erhöht die Dauer Eurer aktiven Effekte von 'Schwarzmacht' um 5 Sek.\n\nDieser Effekt kann kritisch treffen und erhöht die Dauer von 'Schwarzmacht' dann um zusätzlich 50%." }
