entries[395266] = { ["name"] = "Ruf zu den Waffen", ["text"] = "'Waffen der Ordnung' ruft für 12 Sek. [ Braumeister : Niuzao, den Schwarzen Ochsen ] [ Nebelwirker : Chi-Ji, den Roten Kranich ] [ Windläufer : Xuen, den Weißen Tiger / Yu'lon, die Jadeschlange, ] zur Unterstützung an Eure Seite." }
entries[395267] = { ["name"] = "Niuzao den Schwarzen Ochsen beschwören", ["text"] = "40 Meter Reichweite\nSofort 3 min Abklingzeit\nBeschwört für 12 Sek. ein Abbild von Niuzao, dem Schwarzen Ochsen. Niuzao greift Euer Primärziel an und stampft mehrmals auf, was allen Gegnern in der Nähe [ Verbessertes Niuzao den Schwarzen Ochsen beschwören : (200% der Angriffskraft) Schaden und zusätzlich 0% des kürzlich entfernten gestaffelten Schadens zufügt / Schaden zufügt.]\nWährend das Abbild aktiv ist, werden 40% des durch 'Staffeln' verzögerten Schadens stattdessen von Niuzao gestaffelt." }
entries[395268] = { ["name"] = "Ruf zu den Waffen", ["text"] = "Sofort\n'Waffen der Ordnung' ruft für 12 Sek. [ Braumeister : Niuzao, den Schwarzen Ochsen ] [ Nebelwirker : Chi-Ji, den Roten Kranich ] [ Windläufer : Xuen, den Weißen Tiger / Yu'lon, die Jadeschlange, ] zur Unterstützung an Eure Seite.\n(500ms Abklingzeit)" }
entries[395269] = { ["name"] = "Schillerndes Erz", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nBrocken schillernden Erzes werden häufig von sorgfältigen Bergarbeitern gefunden, wenn sie die Dracheninseln absuchen. Wenn Ihr Euch einen Moment Zeit nehmt, diese richtig zu untersuchen, gewinnt Ihr weiteres Wissen über Eure Bergbauspezialisierungen.\n\nIhr könnt diese Woche noch 5 Stück entdecken.\nBeruf:\nBergbau (1)" }
