entries[395275] = { ["name"] = "Traumblüte", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nEine seltene Blume, deren Blütenblätter alle einzeln aufblühen, kann neben anderen Kräutern der Dracheninseln gefunden werden. Sie hat zwar nicht viele direkt für andere Berufe nützliche Eigenschaften, doch wenn Ihr Euch einen Moment Zeit nehmt, sie zu untersuchen, lernt Ihr mehr über die dortige Flora und gewinnt an Wissen über Eure Kräuterkundespezialisierungen.\n\nIhr könnt diese Woche noch 5 Exemplar(e) entdecken.\nBeruf:\nKräuterkunde (1)" }
entries[395277] = { ["name"] = "Teleport: Valdrakken", ["text"] = "3% von Grundmana\nWirken in 10 sek.\nTeleportiert Euch nach Valdrakken." }
