entries[395279] = { ["name"] = "Arkaner Ansturm", ["text"] = "50 Meter Reichweite\nSofort\nEntfesselt einen titanischen Ansturm arkaner Energie.\n\nFügt Gegnern innerhalb von 5 Metern um den Einschlag 40 körperlichen Schaden zu.\n\nUnterbricht das Zauberwirken aller Gegner innerhalb von 5 Metern um den Einschlag.\n\nStößt alle Gegner innerhalb von 5 Metern um den Einschlag zurück." }
