entries[395296] = { ["name"] = "Schwarzmacht", ["text"] = "Sofort\nErhöht den Primärwert Eurer 4 nächsten Verbündeten um (5 + 0 )% Eures eigenen Primärwerts und Ihr verursacht 20% mehr Schaden. Hält 10 Sek. lang an.\n\nKann nur jeweils 4 Verbündete gleichzeitig betreffen und wirkt sich nicht auf Tanks und Heiler aus.\n\n'Eruption', [ Atem der Äonen : 'Atem der Äonen' / 'Tiefer Atem'] und Eure ermächtigten Zauber verlängern die Dauer dieser Effekte." }
